-- Recupera vinculo Peticion de mantenimiento -> Linea / Pedido de venta
-- Origen: Odoo 16 al cierre 30-oct-2026 (3713 peticiones). Los ids coinciden entre 16 y 19.
BEGIN;
CREATE TEMP TABLE _mtto_sol(id int PRIMARY KEY, sol int) ON COMMIT DROP;

UPDATE maintenance_request mr
   SET "x_studio_field_UT6zf" = t.sol
  FROM _mtto_sol t
  JOIN sale_order_line sl ON sl.id = t.sol
 WHERE mr.id = t.id
   AND mr."x_studio_field_UT6zf" IS NULL;

UPDATE maintenance_request mr
   SET "x_studio_field_ypPfL" = sl.order_id
  FROM sale_order_line sl
 WHERE sl.id = mr."x_studio_field_UT6zf"
   AND mr."x_studio_field_ypPfL" IS DISTINCT FROM sl.order_id;

SELECT count(*) AS en_csv,
       count(mr.id) AS existen_en_19,
       count(sl.id) AS linea_existe_en_19
  FROM _mtto_sol t
  LEFT JOIN maintenance_request mr ON mr.id = t.id
  LEFT JOIN sale_order_line sl ON sl.id = t.sol;

SELECT count(*) FILTER (WHERE "x_studio_field_UT6zf" IS NOT NULL) AS con_linea,
       count(*) FILTER (WHERE "x_studio_field_ypPfL" IS NOT NULL) AS con_pedido
  FROM maintenance_request;
COMMIT;
